B.bAl=new A.e("\u0423\u0434\u0430\u0440 \u0443\u0448\u0451\u043b \u0432 \u0437\u0430\u0449\u0438\u0442\u0443. \u041d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043e.","The blow went into the shield. Nothing is lost.")
B.bCz=new A.e("\u0422\u0438\u0445\u0438\u0439 \u0432\u0435\u0447\u0435\u0440 \u043f\u043e\u043a\u043e\u044f: \u043d\u0438\u0442\u0438 \u0422\u043a\u0430\u0447\u0430 \u0442\u044f\u0436\u0435\u043b\u0435\u044e\u0442, \u043e\u043d \u043f\u043b\u0435\u0442\u0451\u0442 \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u0435\u0435.","A quiet evening of calm: the Weaver\u2019s threads grow heavy, he weaves more slowly.")
B.bNy=new A.e("\u0422\u0443\u043c\u0430\u043d \u0442\u0440\u0435\u0432\u043e\u0433\u0438 \u043a\u043e\u0440\u043c\u0438\u0442 \u0422\u043a\u0430\u0447\u0430: \u043e\u043d \u043f\u043b\u0435\u0442\u0451\u0442 \u0431\u044b\u0441\u0442\u0440\u0435\u0435. \u041f\u043e\u043a\u043e\u0439 \u0435\u0433\u043e \u0443\u0442\u0438\u0445\u043e\u043c\u0438\u0440\u0438\u0442.","The fog of anxiety feeds the Weaver: he weaves faster. Calm will settle him.")
B.aCn=new A.C5(B.bCU,B.aJG,B.bG4,B.bMq,B.byG,B.bvz,B.bAl,B.hq,B.bCz,B.dj,B.bNy)
B.bM1=new A.e("\u041e\u043f\u044f\u0442\u044c \u043e\u0448\u0438\u0431\u043a\u0430. \u042f \u043f\u0440\u0438\u0448\u0451\u043b \u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0432\u0430\u0448 \u043f\u0440\u043e\u0432\u0430\u043b.","Another mistake. I\u2019ve come to record your failure.")
B.btM=new A.e("\u041f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u0432 \u043c\u043e\u0451 \u0437\u0435\u0440\u043a\u0430\u043b\u043e: \u0432\u043e\u0442 \u0432\u0430\u0448\u0430 \u0441\u043b\u0430\u0431\u043e\u0441\u0442\u044c.","Look into my mirror: there is your weakness.")
B.bDQ=new A.e("\u041d\u0435\u0443\u0436\u0435\u043b\u0438 \u0432\u044b \u0434\u0443\u043c\u0430\u043b\u0438, \u0447\u0442\u043e \u0441\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u0441\u044c?","Did you really think you\u2019d manage?")
B.bzN=new A.e("\u041a\u0430\u0436\u0434\u044b\u0439 \u0432\u0430\u0448 \u0448\u0430\u0433 \u0434\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043c\u043e\u044e \u043f\u0440\u0430\u0432\u043e\u0442\u0443.","Every step you take proves me right.")
