B.cjZ=new A.jg(B.bHo,B.bQm,B.but,B.b0i,null)
B.bx9=new A.e("\u0412\u0435\u0440\u0430 \u0432 \u0442\u043e, \u0447\u0442\u043e \u0434\u0443\u0448\u0435\u0432\u043d\u043e\u0433\u043e \u0442\u0435\u043f\u043b\u0430 \u0432 \u043c\u0438\u0440\u0435 \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u043c\u0430\u043b\u043e, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0441\u043f\u043e\u0441\u043e\u0431 \u0432\u044b\u0436\u0438\u0442\u044c \u2014 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0441\u0435\u0431\u044f, \u0432\u043e\u0441\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044f \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0445 \u043a\u0430\u043a \u0443\u0433\u0440\u043e\u0437\u0443 \u0438\u043b\u0438 \u0440\u0435\u0441\u0443\u0440\u0441.","The belief that there is too little emotional warmth in the world, so the only way to survive is to rely solely on yourself, viewing others as a threat or a resource.")
B.bL0=new A.e("\u042d\u0442\u043e \u043b\u0435\u0434\u044f\u043d\u043e\u0435 \u0434\u0435\u0440\u0435\u0432\u043e \u043f\u0440\u043e\u0440\u0430\u0441\u0442\u0430\u0435\u0442 \u0438\u0437 \u0445\u043e\u043b\u043e\u0434\u043d\u043e\u0433\u043e, \u043e\u0442\u0432\u0435\u0440\u0433\u0430\u044e\u0449\u0435\u0433\u043e \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f, \u0433\u0434\u0435 \u0431\u043b\u0438\u0437\u043e\u0441\u0442\u044c \u043f\u0440\u0438\u043d\u043e\u0441\u0438\u043b\u0430 \u043b\u0438\u0448\u044c \u0431\u043e\u043b\u044c \u0438\u043b\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043b\u0430\u0441\u044c \u043f\u0440\u043e\u0442\u0438\u0432 \u0442\u0435\u0431\u044f. \u041e\u043d\u043e \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043e\u0442 \u043d\u0435\u0432\u044b\u043d\u043e\u0441\u0438\u043c\u043e\u0433\u043e \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430 \u043b\u044e\u0431\u0432\u0438: \u0435\u0441\u043b\u0438 \u044f \u0440\u0435\u0448\u0443, \u0447\u0442\u043e \u0442\u0435\u043f\u043b\u043e \u043c\u043d\u0435 \u0432\u043e\u043e\u0431\u0449\u0435 \u043d\u0435 \u043d\u0443\u0436\u043d\u043e, \u0435\u0433\u043e \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u0435\u0442 \u043c\u0435\u043d\u044f \u0440\u0430\u043d\u0438\u0442\u044c.","This icy tree grows from a cold, rejecting environment where closeness brought only pain or was used against you. It protects against an unbearable deficit of love: if I decide that I don't need warmth at all, its absence will stop hurting me.")
