B.bgF={"\u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u043d\u043e\u0441\u0442\u044c":0,"\u043b\u044e\u0431\u043e\u0432\u044c":1,"\u043d\u0430\u0434\u0435\u0436\u0434\u0430":2,"\u043f\u043e\u043c\u043e\u0449\u044c":3,"\u043f\u0440\u043e\u0449\u0435\u043d\u0438\u0435":4,"\u0440\u0430\u0434\u043e\u0441\u0442\u044c":5,"\u0440\u043e\u0441\u0442":6,"\u0441\u043c\u0438\u0440\u0435\u043d\u0438\u0435":7}
B.bWK=new A.o(["\u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u043d\u043e\u0441\u0442\u044c","gratitude","\u0412\u044b \u043e\u0431\u0430 \u0443\u043c\u0435\u0435\u0442\u0435 \u0437\u0430\u043c\u0435\u0447\u0430\u0442\u044c \u0445\u043e\u0440\u043e\u0448\u0435\u0435. \u0411\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u043d\u043e\u0441\u0442\u044c \u0434\u0435\u043b\u0430\u0435\u0442 \u043e\u0431\u044b\u0447\u043d\u044b\u0435 \u0434\u043d\u0438 \u0442\u0451\u043f\u043b\u044b\u043c\u0438.","You both notice the good. Gratitude makes ordinary days warm."])
B.bZu=new A.o(["\u043b\u044e\u0431\u043e\u0432\u044c","love","\u0412 \u043e\u0431\u043e\u0438\u0445 \u043c\u0438\u0440\u0430\u0445 \u0435\u0441\u0442\u044c \u043c\u044b\u0441\u043b\u0438 \u043e \u043b\u044e\u0431\u0432\u0438. \u0412\u0430\u043c \u0435\u0441\u0442\u044c \u0447\u0435\u043c \u0441\u043e\u0433\u0440\u0435\u0442\u044c \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0430.","Both worlds have thoughts of love. You have something to warm each other with."])
B.bYR=new A.o(["\u043d\u0430\u0434\u0435\u0436\u0434\u0430","hope","\u041e\u0431\u0430 \u0443\u043c\u0435\u0435\u0442\u0435 \u043d\u0430\u0434\u0435\u044f\u0442\u044c\u0441\u044f. \u0412 \u0442\u0440\u0443\u0434\u043d\u0443\u044e \u043c\u0438\u043d\u0443\u0442\u0443 \u043e\u0434\u0438\u043d \u043d\u0430\u043f\u043e\u043c\u043d\u0438\u0442 \u0434\u0440\u0443\u0433\u043e\u043c\u0443, \u0447\u0442\u043e \u0432\u0441\u0451 \u0435\u0449\u0451 \u043c\u043e\u0436\u0435\u0442 \u0441\u0442\u0430\u0442\u044c \u0445\u043e\u0440\u043e\u0448\u043e.","You both can hope. In a hard moment one will remind the other that things can still turn out well."])
B.c0G=new A.o(["\u043f\u043e\u043c\u043e\u0449\u044c","helping","\u041e\u0431\u043e\u0438\u043c \u0432\u0430\u0436\u043d\u043e \u043f\u043e\u043c\u043e\u0433\u0430\u0442\u044c. \u0412\u044b \u043b\u0435\u0433\u043a\u043e \u043f\u043e\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435 \u043f\u043b\u0435\u0447\u043e, \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0435 \u0437\u0430\u0431\u044b\u0432\u0430\u0439\u0442\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u044c \u043f\u043e\u043c\u043e\u0449\u044c.","Helping matters to you both. You will easily lend a shoulder; just remember to accept help too."])
B.bYz=new A.o(["\u043f\u0440\u043e\u0449\u0435\u043d\u0438\u0435","forgiveness","\u0412\u044b \u043e\u0431\u0430 \u0443\u043c\u0435\u0435\u0442\u0435 \u043f\u0440\u043e\u0449\u0430\u0442\u044c. \u041e\u0431\u0438\u0434\u044b \u0443 \u0432\u0430\u0441 \u043d\u0435 \u0443\u0441\u043f\u0435\u0432\u0430\u044e\u0442 \u0441\u0442\u0430\u0442\u044c \u0441\u0442\u0435\u043d\u0430\u043c\u0438.","You both can forgive. Grievances don't get the chance to become walls."])
B.bYP=new A.o(["\u0440\u0430\u0434\u043e\u0441\u0442\u044c","joy","\u041e\u0431\u0430 \u0443\u043c\u0435\u0435\u0442\u0435 \u0440\u0430\u0434\u043e\u0432\u0430\u0442\u044c\u0441\u044f. \u0420\u0430\u0434\u043e\u0441\u0442\u044c, \u0440\u0430\u0437\u0434\u0435\u043b\u0451\u043d\u043d\u0430\u044f \u043d\u0430 \u0434\u0432\u043e\u0438\u0445, \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u0431\u043e\u043b\u044c\u0448\u0435.","You both know how to be glad. Joy shared between two grows larger."])
B.bY0=new A.o(["\u0440\u043e\u0441\u0442","growth","\u041e\u0431\u043e\u0438\u043c \u0432\u0430\u0436\u043d\u043e \u0440\u0430\u0441\u0442\u0438. \u0412\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u0431\u044b\u0442\u044c \u0434\u0440\u0443\u0433 \u0434\u043b\u044f \u0434\u0440\u0443\u0433\u0430 \u043f\u043e\u043f\u0443\u0442\u043d\u044b\u043c \u0432\u0435\u0442\u0440\u043e\u043c.","Growth matters to you both. You can be a tailwind for each other."])
B.c0S=new A.o(["\u0441\u043c\u0438\u0440\u0435\u043d\u0438\u0435","humility","\u041e\u0431\u0430 \u0443\u043c\u0435\u0435\u0442\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u044c \u0442\u043e, \u0447\u0442\u043e \u043d\u0435 \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c. \u042d\u0442\u043e \u0434\u0430\u0451\u0442 \u043f\u043e\u043a\u043e\u0439 \u0432\u0430\u0448\u0438\u043c \u0441\u043f\u043e\u0440\u0430\u043c.","You both can accept what cannot be changed. That brings peace to your arguments."])
B.Ty=new A.aK(B.bgF,[B.bWK,B.bZu,B.bYR,B.c0G,B.bYz,B.bYP,B.bY0,B.c0S],t.HB)
B.bgV={"\u0414\u0435\u0440\u0435\u0432\u043e \u0426\u0435\u043d\u043d\u043e\u0441\u0442\u0438":0,"\u0426\u0435\u043d\u043d\u043e\u0441\u0442\u044c":1,"\u042f \u0434\u043e\u0441\u0442\u043e\u0438\u043d \u043b\u044e\u0431\u0432\u0438":2,[u.wr]:3,"\u0414\u0435\u0440\u0435\u0432\u043e \u041d\u0438\u0447\u0442\u043e\u0436\u043d\u043e\u0441\u0442\u0438":4,"\u041d\u0438\u0447\u0442\u043e\u0436\u043d\u043e\u0441\u0442\u044c":5,"\u041c\u0435\u043d\u044f \u0442\u0435\u0440\u043f\u044f\u0442, \u043f\u043e\u043a\u0430 \u044f \u043f\u043e\u043b\u0435\u0437\u0435\u043d":6,[u.fq]:7,"\u0414\u0435\u0440\u0435\u0432\u043e \u0414\u043e\u0432\u0435\u0440\u0438\u044f":8,"\u0414\u043e\u0432\u0435\u0440\u0438\u0435":9,"\u041c\u0438\u0440 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u0435\u043d":10,[u.jx]:11,"\u0414\u0435\u0440\u0435\u0432\u043e \u0412\u0440\u0430\u0436\u0434\u0435\u0431\u043d\u043e\u0441\u0442\u0438":12,"\u0412\u0440\u0430\u0436\u0434\u0435\u0431\u043d\u043e\u0441\u0442\u044c":13,"\u041d\u0435 \u0440\u0430\u0441\u0441\u043b\u0430\u0431\u043b\u044f\u0439\u0441\u044f":14,[u.p7]:15,"\u0414\u0435\u0440\u0435\u0432\u043e \u0421\u0438\u043b\u044b":16,"\u0421\u0438\u043b\u0430":17,"\u042f \u0441\u043f\u0440\u0430\u0432\u043b\u044e\u0441\u044c":18,[u.l5]:19,"\u0414\u0435\u0440\u0435\u0432\u043e \u0411\u0435\u0441\u0441\u0438\u043b\u0438\u044f":20,"\u0411\u0435\u0441\u0441\u0438\u043b\u0438\u0435":21,"\u0427\u0442\u043e \u0442\u043e\u043b\u043a\u0443":22,[u.w2]:23,"\u0414\u0435\u0440\u0435\u0432\u043e \u041f\u0440\u0438\u043d\u044f\u0442\u0438\u044f":24,"\u041f\u0440\u0438\u043d\u044f\u0442\u0438\u0435":25,"\u0412\u0441\u0435\u043c\u0443 \u0441\u0432\u043e\u0451 \u043c\u0435\u0441\u0442\u043e":26,[u.jW]:27,"\u0414\u0435\u0440\u0435\u0432\u043e \u041e\u0431\u0438\u0434\u044b":28,"\u041e\u0431\u0438\u0434\u0430":29,"\u0422\u0430\u043a \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u043e \u0431\u044b\u0442\u044c":30,[u.bl]:31,"\u0414\u0435\u0440\u0435\u0432\u043e \u041b\u044e\u0431\u0432\u0438":32,"\u041b\u044e\u0431\u043e\u0432\u044c":33,"\u0414\u043e\u0431\u0440\u043e \u043f\u0440\u0438\u0443\u043c\u043d\u043e\u0436\u0430\u0435\u0442\u0441\u044f":34,[u.yI]:35,"\u0414\u0435\u0440\u0435\u0432\u043e \u041e\u0442\u0447\u0443\u0436\u0434\u0435\u043d\u0438\u044f":36,"\u041e\u0442\u0447\u0443\u0436\u0434\u0435\u043d\u0438\u0435":37,"\u0425\u043e\u043b\u043e\u0434\u043d\u043e\u0435 \u0441\u0435\u0440\u0434\u0446\u0435":38,[u.BS]:39,"\u0414\u0435\u0440\u0435\u0432\u043e \u041f\u0440\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u044f":40,"\u041f\u0440\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u0435":41,"\u041c\u043e\u0439 \u0433\u043e\u043b\u043e\u0441 \u0432\u0430\u0436\u0435\u043d":42,[u.CH]:43,"\u0414\u0435\u0440\u0435\u0432\u043e \u041d\u0435\u0432\u0438\u0434\u0438\u043c\u043a\u0438":44,"\u041d\u0435\u0432\u0438\u0434\u0438\u043c\u043a\u0430":45,"\u041d\u0435 \u0432\u044b\u0441\u043e\u0432\u044b\u0432\u0430\u0439\u0441\u044f":46,[u.yM]:47,"\u0414\u0435\u0440\u0435\u0432\u043e \u0421\u043c\u044b\u0441\u043b\u0430":48,"\u0421\u043c\u044b\u0441\u043b":49,"\u0412\u0441\u0451 \u043d\u0435 \u0437\u0440\u044f":50,[u.p6]:51,"\u0414\u0435\u0440\u0435\u0432\u043e \u041f\u0443\u0441\u0442\u043e\u0442\u044b":52,"\u041f\u0443\u0441\u0442\u043e\u0442\u0430":53,"\u0417\u0430\u0447\u0435\u043c \u0432\u0441\u0451 \u044d\u0442\u043e":54,[u.P]:55,"\u042f \u0446\u0435\u043d\u0435\u043d \u0441\u0430\u043c \u043f\u043e \u0441\u0435\u0431\u0435":56,"\u042f \u043e\u0448\u0438\u0431\u0441\u044f, \u043d\u043e \u044f \u043d\u0435 \u043e\u0448\u0438\u0431\u043a\u0430":57,"\u041c\u043d\u0435 \u043c\u043e\u0436\u043d\u043e \u043e\u0442\u0434\u044b\u0445\u0430\u0442\u044c, \u043d\u0435 \u0437\u0430\u0441\u043b\u0443\u0436\u0438\u0432 \u044d\u0442\u043e\u0433\u043e":58,"\u041c\u043d\u0435 \u043c\u043e\u0436\u043d\u043e \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u044c \xab\u043d\u0435\u0442\xbb":59,"\u041c\u043e\u0438 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u0438\u0435 \u043f\u043e\u0431\u0435\u0434\u044b \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f":60,"\u042f \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0445\u043e\u0440\u043e\u0448":61,"\u0421\u043a\u043e\u0440\u043e \u0432\u0441\u0435 \u043f\u043e\u0439\u043c\u0443\u0442, \u0447\u0442\u043e \u044f \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0441\u0442\u043e\u044e":62,"\u041c\u043e\u0438 \u043d\u0443\u0436\u0434\u044b \u2014 \u043f\u043e\u0442\u043e\u043c":63,"\u041b\u0438\u0431\u043e \u0438\u0434\u0435\u0430\u043b\u044c\u043d\u043e, \u043b\u0438\u0431\u043e \u043d\u0438\u043a\u0430\u043a":64,"\u042f \u043c\u043e\u0433\u0443 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043e \u043f\u043e\u043c\u043e\u0449\u0438":65,"\u041d\u0430\u043f\u043e\u043c\u043d\u0438\u0442\u044c \u043e \u0441\u0435\u0431\u0435 \u2014 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e":66,"\u0411\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u043e \u043b\u044e\u0434\u0435\u0439 \u043d\u0435 \u0436\u0435\u043b\u0430\u044e\u0442 \u043c\u043d\u0435 \u0437\u043b\u0430":67,"\u0411\u0443\u0434\u0443\u0449\u0435\u0435 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u0431\u0440\u044b\u043c":68,"\u041c\u0435\u043d\u044f \u0438\u0433\u043d\u043e\u0440\u0438\u0440\u0443\u044e\u0442 \u043d\u0430\u0440\u043e\u0447\u043d\u043e":69,"\u0412\u0441\u0435\u043c \u043e\u0442 \u043c\u0435\u043d\u044f \u0447\u0442\u043e-\u0442\u043e \u043d\u0443\u0436\u043d\u043e":70,"\u041d\u0435 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0439, \u0447\u0442\u043e \u0442\u0435\u0431\u0435 \u0432\u0430\u0436\u043d\u043e":71,"\u0412\u043e\u0442-\u0432\u043e\u0442 \u0441\u043b\u0443\u0447\u0438\u0442\u0441\u044f \u0447\u0442\u043e-\u0442\u043e \u0441\u0442\u0440\u0430\u0448\u043d\u043e\u0435":72,"\u0428\u0430\u0433 \u0437\u0430 \u0448\u0430\u0433\u043e\u043c \u044f \u0441\u043f\u0440\u0430\u0432\u043b\u044e\u0441\u044c":73,"\u041c\u043e\u0436\u043d\u043e \u043f\u043e\u043f\u0440\u043e\u0431\u043e\u0432\u0430\u0442\u044c \u0438\u043d\u0430\u0447\u0435":74,"\u041a\u043e\u0435-\u0447\u0442\u043e \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u043c\u0435\u043d\u044f":75,"\u0423 \u043c\u0435\u043d\u044f \u043b\u0430\u043f\u043a\u0438":76,"\u0412\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u0441\u044f":77,"\u041f\u0443\u0441\u0442\u044c \u043a\u0442\u043e-\u043d\u0438\u0431\u0443\u0434\u044c \u0440\u0435\u0448\u0438\u0442 \u0437\u0430 \u043c\u0435\u043d\u044f":78,"\u0427\u0442\u043e \u044f \u043c\u043e\u0433\u0443 \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0441\u0435\u0439\u0447\u0430\u0441?":79,[u.cQ]:80,"\u0413\u0440\u0443\u0441\u0442\u0438\u0442\u044c \u2014 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e":81,"\u042d\u0442\u043e \u043f\u0440\u043e\u0439\u0434\u0451\u0442":82,"\u0420\u0435\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u0430 \u043a\u043e \u043c\u043d\u0435":83,"\u042f \u044d\u0442\u043e\u0433\u043e \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u0440\u043e\u0449\u0443":84,"\u0415\u0441\u043b\u0438 \u0431\u044b \u0442\u043e\u0433\u0434\u0430 \u0432\u0441\u0451 \u0431\u044b\u043b\u043e \u0438\u043d\u0430\u0447\u0435\u2026":85,"\u041c\u0435\u043d\u044f \u043c\u043e\u0436\u043d\u043e \u043b\u044e\u0431\u0438\u0442\u044c":86,"\u0423 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0435\u0441\u0442\u044c \u0441\u0432\u043e\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0430":87,"\u041c\u043d\u0435 \u0435\u0441\u0442\u044c \u0437\u0430 \u0447\u0442\u043e \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u0438\u0442\u044c":88,"\u0427\u0443\u0436\u0430\u044f \u0440\u0430\u0434\u043e\u0441\u0442\u044c \u043d\u0435 \u043e\u0442\u043d\u0438\u043c\u0430\u0435\u0442 \u043c\u043e\u0435\u0439":89,"\u0414\u043e\u043b\u0433\u0430\u044f \u0437\u043b\u043e\u0441\u0442\u044c \u0443\u0442\u043e\u043c\u043b\u044f\u0435\u0442, \u0430 \u0442\u0435\u043f\u043b\u043e \u043f\u0438\u0442\u0430\u0435\u0442":90,"\u041c\u043d\u0435 \u0432\u0441\u0435 \u0434\u043e\u043b\u0436\u043d\u044b":91,"\u0412\u0441\u0435 \u0440\u0430\u043d\u043e \u0438\u043b\u0438 \u043f\u043e\u0437\u0434\u043d\u043e \u0443\u0445\u043e\u0434\u044f\u0442":92,"\u041c\u043d\u0435 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043d\u0443\u0436\u0435\u043d":93,"\u041c\u043d\u0435 \u043d\u0435\u0442 \u0434\u0435\u043b\u0430 \u0434\u043e \u0447\u0443\u0436\u0438\u0445 \u043f\u0440\u043e\u0431\u043b\u0435\u043c":94,"\u041c\u043e\u0451 \u043c\u043d\u0435\u043d\u0438\u0435 \u0438\u043c\u0435\u0435\u0442 \u043f\u0440\u0430\u0432\u043e \u0437\u0432\u0443\u0447\u0430\u0442\u044c":95,"\u042f \u043c\u043e\u0433\u0443 \u0441\u043a\u0430\u0437\u0430\u0442\u044c, \u0447\u0435\u0433\u043e \u0445\u043e\u0447\u0443":96,"\u041c\u043e\u0438 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u0435 \u0447\u0443\u0432\u0441\u0442\u0432\u0430 \u043c\u043e\u0436\u043d\u043e \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c":97,"\u041c\u0435\u043d\u044f \u0432\u044b\u0441\u043c\u0435\u044e\u0442":98,"\u041f\u0440\u043e\u0449\u0435 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0442\u044c\u0441\u044f":99,"\u041c\u043e\u0438 \u0447\u0443\u0432\u0441\u0442\u0432\u0430 \u0432\u0441\u0435\u0445 \u0443\u0442\u043e\u043c\u044f\u0442":100,"\u042f \u0437\u043d\u0430\u044e, \u0447\u0442\u043e \u0434\u043b\u044f \u043c\u0435\u043d\u044f \u0432\u0430\u0436\u043d\u043e":101,"\u0417\u0430\u0432\u0442\u0440\u0430 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0441\u0432\u0435\u0442\u043b\u0435\u0435":102,"\u041c\u0430\u043b\u0435\u043d\u044c\u043a\u0438\u0435 \u0434\u0435\u043b\u0430 \u0442\u043e\u0436\u0435 \u0438\u043c\u0435\u044e\u0442 \u0432\u0435\u0441":103,"\u0414\u0430\u0436\u0435 \u0442\u044f\u0436\u0451\u043b\u044b\u0439 \u0434\u0435\u043d\u044c \u0447\u0435\u043c\u0443-\u0442\u043e \u0443\u0447\u0438\u0442":104,"\u042f \u0447\u0430\u0441\u0442\u044c \u0447\u0435\u0433\u043e-\u0442\u043e \u0431\u043e\u043b\u044c\u0448\u0435\u0433\u043e":105,"\u0412\u043f\u0435\u0440\u0435\u0434\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u0445\u043e\u0440\u043e\u0448\u0435\u0433\u043e":106,"\u041b\u0438\u0448\u044c \u0431\u044b \u0443\u0431\u0438\u0442\u044c \u0432\u0440\u0435\u043c\u044f":107,"\u041d\u0435\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u043d\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435":108,[u.m]:109,"\u041d\u0430\u0432\u0435\u0440\u043d\u043e\u0435, \u0437\u0430\u043d\u044f\u0442. \u041e\u0442\u0432\u0435\u0442\u0438\u0442, \u043a\u043e\u0433\u0434\u0430 \u0441\u043c\u043e\u0436\u0435\u0442.":110,[u.wb]:111,"\u0417\u043d\u0430\u0447\u0438\u0442, \u0438\u0433\u043d\u043e\u0440\u0438\u0440\u0443\u0435\u0442 \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u044c\u043d\u043e. \u0417\u0430\u043f\u043e\u043c\u043d\u044e.":112,"\u041d\u0443 \u0438 \u043b\u0430\u0434\u043d\u043e. \u041d\u0438\u043a\u043e\u043c\u0443 \u044f, \u0432\u0438\u0434\u043d\u043e, \u043d\u0435 \u043d\u0443\u0436\u0435\u043d.":113,"\u041d\u0430\u043f\u0438\u0448\u0443 \u0435\u0449\u0451 \u0440\u0430\u0437 \u2014 \u0432\u0434\u0440\u0443\u0433 \u043d\u0435 \u0437\u0430\u043c\u0435\u0442\u0438\u043b.":114,"\u041f\u0435\u0440\u0432\u0430\u044f \u043d\u0435\u0443\u0434\u0430\u0447\u0430":115,[u.mA]:116,[u.C8]:117,[u.cF]:118,[u.mg]:119,[u.DC]:120,[u.yW]:121,"\u0418\u0434\u0435\u044e \u043e\u0442\u0432\u0435\u0440\u0433\u043b\u0438":122,[u.b8]:123,[u.AP]:124,"\u041a\u0430\u043a \u0432\u0441\u0435\u0433\u0434\u0430. \u041c\u0438\u0440 \u043d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432 \u043a\u043e \u043c\u043d\u0435.":125,[u.c]:126,[u.Ad]:127,[u.I]:128,"\u041f\u043b\u0430\u043d\u044b \u0440\u0443\u0448\u0430\u0442\u0441\u044f":129,[u.fW]:130,"\u0416\u0430\u043b\u044c. \u041f\u043e\u0433\u0440\u0443\u0449\u0443 \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u2014 \u0438\u043c\u0435\u044e \u043f\u0440\u0430\u0432\u043e.":131,[u.o5]:132,[u.r]:133,[u.xt]:134,[u.EW]:135,"\u0427\u0443\u0436\u0438\u0435 \u0441\u043b\u0451\u0437\u044b":136,[u.l6]:137,[u.sC]:138,"\u041d\u0435 \u043c\u043e\u0451 \u0434\u0435\u043b\u043e. \u0423 \u0432\u0441\u0435\u0445 \u0441\u0432\u043e\u0438 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b.":139,[u.ex]:140,[u.l9]:141,[u.jL]:142,"\u0414\u0440\u0443\u0433\u043e\u0435 \u043c\u043d\u0435\u043d\u0438\u0435":143,[u.qW]:144,"\u0421\u043a\u0430\u0436\u0443: \u043c\u043d\u0435 \u0435\u0441\u0442\u044c \u0447\u0442\u043e \u0441\u043a\u0430\u0437\u0430\u0442\u044c.":145,"\u041f\u0440\u043e\u043c\u043e\u043b\u0447\u0443. \u0422\u0438\u0448\u0435 \u0435\u0434\u0435\u0448\u044c \u2014 \u0434\u0430\u043b\u044c\u0448\u0435 \u0431\u0443\u0434\u0435\u0448\u044c.":146,"\u0412\u0434\u0440\u0443\u0433 \u0437\u0430\u0441\u043c\u0435\u044e\u0442. \u041b\u0443\u0447\u0448\u0435 \u043c\u043e\u043b\u0447\u0430\u0442\u044c.":147,"\u0421\u043a\u0430\u0436\u0443 \u043a\u043e\u0440\u043e\u0442\u043a\u043e, \u0434\u0430\u0436\u0435 \u0435\u0441\u043b\u0438 \u0433\u043e\u043b\u043e\u0441 \u0434\u0440\u043e\u0436\u0438\u0442.":148,[u.cX]:149,"\u041f\u0443\u0441\u0442\u043e\u0435 \u0432\u043e\u0441\u043a\u0440\u0435\u0441\u0435\u043d\u044c\u0435":150,[u.z6]:151,"\u041d\u0430\u0439\u0434\u0443 \u0432 \u044d\u0442\u043e\u043c \u0434\u043d\u0435 \u043e\u0434\u043d\u0443 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u0443\u044e \u0438\u0441\u043a\u0440\u0443.":152,[u.EV]:153,"\u0410 \u043a\u0430\u043a\u0430\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u0430? \u0412\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u0432\u0441\u0451 \u0441\u043e\u0442\u0440\u0451\u0442\u0441\u044f.":154,[u.B1]:155,[u.Et]:156,"\u041f\u043e\u0445\u0432\u0430\u043b\u0430":157,"\u0422\u0435\u0431\u044f \u0438\u0441\u043a\u0440\u0435\u043d\u043d\u0435 \u0445\u0432\u0430\u043b\u044f\u0442 \u0437\u0430 \u0441\u0434\u0435\u043b\u0430\u043d\u043d\u043e\u0435.":158,"\u0421\u043f\u0430\u0441\u0438\u0431\u043e. \u041c\u043d\u0435 \u043f\u0440\u0438\u044f\u0442\u043d\u043e.":159,"\u042d\u0442\u043e \u043e\u043d\u0438 \u0438\u0437 \u0432\u0435\u0436\u043b\u0438\u0432\u043e\u0441\u0442\u0438.":160,[u.BT]:161,"\u0418\u043d\u0442\u0435\u0440\u0435\u0441\u043d\u043e, \u0447\u0442\u043e \u0438\u043c \u043e\u0442 \u043c\u0435\u043d\u044f \u043d\u0443\u0436\u043d\u043e?":162,[u.nP]:163,"\u041d\u0443\u0436\u043d\u0430 \u0442\u0438\u0448\u0438\u043d\u0430":164,[u.pr]:165,"\u041f\u043e\u043f\u0440\u043e\u0448\u0443 \u0432\u0435\u0436\u043b\u0438\u0432\u043e: \u043c\u043e\u0451 \u0437\u0430\u0432\u0442\u0440\u0430 \u0442\u043e\u0436\u0435 \u0432\u0430\u0436\u043d\u043e.":166,"\u041d\u0435 \u0431\u0443\u0434\u0443 \u043d\u0438\u043a\u043e\u0433\u043e \u043d\u0430\u043f\u0440\u044f\u0433\u0430\u0442\u044c. \u042f \u0438 \u0442\u0430\u043a \u043e\u0431\u0443\u0437\u0430.":167,"\u041f\u043e\u0442\u0435\u0440\u043f\u043b\u044e. \u041c\u043e\u0438 \u043d\u0443\u0436\u0434\u044b \u2014 \u043f\u043e\u0442\u043e\u043c.":168,"\u0411\u0435\u0441\u043f\u043e\u043b\u0435\u0437\u043d\u043e: \u0432\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043d\u0435 \u043f\u043e\u0441\u043b\u0443\u0448\u0430\u044e\u0442.":169,"\u041f\u0440\u044f\u043c\u043e \u0441\u043a\u0430\u0436\u0443, \u0447\u0442\u043e \u043c\u043d\u0435 \u043d\u0443\u0436\u043d\u043e.":170,"\u0412\u044b\u0445\u043e\u0434\u043d\u043e\u0439 \u0431\u0435\u0437 \u0441\u0438\u043b":171,[u.uo]:172,[u.lJ]:173,[u.k4]:174,"\u0421\u0434\u0435\u043b\u0430\u044e \u043e\u0434\u0438\u043d \u043f\u0443\u043d\u043a\u0442, \u0430 \u043f\u043e\u0442\u043e\u043c \u043e\u0442\u0434\u044b\u0445.":175,"\u0412\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043d\u0435 \u0443\u0441\u043f\u0435\u044e. \u041d\u0435\u0442 \u0441\u043c\u044b\u0441\u043b\u0430 \u043d\u0430\u0447\u0438\u043d\u0430\u0442\u044c.":176,[u.Eb]:177,"\u0417\u0430\u0431\u044b\u0442\u043e\u0435 \u043e\u0431\u0435\u0449\u0430\u043d\u0438\u0435":178,[u.gR]:179,[u.z3]:180,"\u042f \u0443\u0436\u0430\u0441\u043d\u044b\u0439 \u0447\u0435\u043b\u043e\u0432\u0435\u043a. \u0412\u0435\u0447\u043d\u043e \u0432\u0441\u0451 \u043f\u043e\u0440\u0447\u0443.":181,"\u041f\u0443\u0441\u0442\u044c \u0441\u0430\u043c \u043d\u0430\u043f\u043e\u043c\u0438\u043d\u0430\u0435\u0442. \u041c\u043d\u0435 \u0432\u0441\u0435 \u0434\u043e\u043b\u0436\u043d\u044b.":182,[u.D7]:183,[u.kF]:184,"\u041d\u0435\u0443\u0434\u0430\u0447\u043d\u043e\u0435 \u0444\u043e\u0442\u043e":185,[u.t9]:186,[u.rN]:187,"\u0423\u0436\u0430\u0441. \u0421\u043e \u043c\u043d\u043e\u0439 \u0447\u0442\u043e-\u0442\u043e \u043d\u0435 \u0442\u0430\u043a.":188,"\u0411\u043e\u043b\u044c\u0448\u0435 \u043d\u0438\u043a\u0430\u043a\u0438\u0445 \u0444\u043e\u0442\u043e. \u041d\u0435 \u0432\u044b\u0441\u043e\u0432\u044b\u0432\u0430\u0442\u044c\u0441\u044f.":189,"\u041f\u043e\u0441\u043c\u0435\u044e\u0441\u044c. \u042f \u0442\u0430\u043a\u043e\u0439, \u043a\u0430\u043a\u043e\u0439 \u0435\u0441\u0442\u044c.":190,"\u0412\u0441\u0435 \u043d\u0430\u0432\u0435\u0440\u043d\u044f\u043a\u0430 \u0431\u0443\u0434\u0443\u0442 \u0441\u043c\u0435\u044f\u0442\u044c\u0441\u044f.":191,"\u041d\u043e\u0432\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f":192,[u.Ff]:193,"\u041b\u044e\u0434\u0438 \u043c\u043e\u0433\u0443\u0442 \u043f\u043e\u043c\u043e\u0447\u044c. \u0421\u043f\u0440\u043e\u0448\u0443, \u0447\u0442\u043e \u0442\u0443\u0442 \u043a\u0430\u043a.":194,[u.W]:195,[u.de]:196,[u.vB]:197,[u.ny]:198,"\u041d\u0435 \u0432\u0435\u0440\u043d\u0443\u043b\u0438":199,[u.Z]:200,[u.zz]:201,"\u0422\u0430\u043a \u0438 \u0435\u0441\u0442\u044c: \u0432\u0435\u0440\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f \u043d\u0438\u043a\u043e\u043c\u0443.":202,"\u0411\u043e\u043b\u044c\u0448\u0435 \u043d\u0438\u043a\u043e\u043c\u0443 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0430\u043c.":203,"\u0421\u0430\u043c \u0432\u0438\u043d\u043e\u0432\u0430\u0442, \u0447\u0442\u043e \u0434\u0430\u043b. \u0412\u0435\u0447\u043d\u043e \u0432\u0441\u0451 \u043f\u043e\u0440\u0447\u0443.":204,"\u0417\u043d\u0430\u0447\u0438\u0442, \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u044c\u043d\u043e. \u041d\u0435 \u043f\u0440\u043e\u0449\u0443.":205,"\u041d\u0435\u0437\u043d\u0430\u043a\u043e\u043c\u0435\u0446 \u0441\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u0434\u043e\u0440\u043e\u0433\u0443":206,[u.cy]:207,[u.Bv]:208,"\u041d\u0430\u0432\u0435\u0440\u043d\u044f\u043a\u0430 \u0443\u043b\u043e\u0432\u043a\u0430. \u041f\u0440\u043e\u0439\u0434\u0443 \u043c\u0438\u043c\u043e.":209,[u.yu]:210,"\u0420\u0430\u0441\u0442\u0435\u0440\u044f\u044e\u0441\u044c \u0438 \u043f\u0440\u043e\u043c\u043e\u043b\u0447\u0443.":211,[u.CT]:212,"\u0422\u0440\u0435\u0442\u0438\u0439 \u0434\u0435\u043d\u044c \u043d\u0435 \u0432\u044b\u0445\u043e\u0434\u0438\u0442":213,[u.a]:214,"\u041f\u043e\u043f\u0440\u043e\u0448\u0443 \u043f\u043e\u043c\u043e\u0449\u0438: \u044f \u043c\u043e\u0433\u0443 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c.":215,[u.CB]:216,"\u041f\u0443\u0441\u0442\u044c \u043a\u0442\u043e-\u043d\u0438\u0431\u0443\u0434\u044c \u0440\u0435\u0448\u0438\u0442 \u0437\u0430 \u043c\u0435\u043d\u044f.":217,"\u041f\u043e\u043f\u0440\u043e\u0431\u0443\u044e \u0441\u043e\u0432\u0441\u0435\u043c \u0434\u0440\u0443\u0433\u0438\u043c \u0441\u043f\u043e\u0441\u043e\u0431\u043e\u043c.":218,"\u041d\u0438\u043a\u0442\u043e \u043d\u0435 \u0434\u043e\u043b\u0436\u0435\u043d \u0432\u0438\u0434\u0435\u0442\u044c, \u0447\u0442\u043e \u043c\u043d\u0435 \u0442\u0440\u0443\u0434\u043d\u043e.":219,"\u041e\u043f\u0430\u0437\u0434\u044b\u0432\u0430\u0435\u0442 \u0438 \u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442":220,[u.A]:221,[u.gj]:222,"\u0421\u043e \u043c\u043d\u043e\u0439 \u0442\u0430\u043a \u0432\u0441\u0435\u0433\u0434\u0430. \u041d\u0438\u043a\u043e\u043c\u0443 \u044f \u043d\u0435 \u043d\u0443\u0436\u0435\u043d.":223,[u.lA]:224,[u.DY]:225,[u.r2]:226,"\u041d\u043e\u0432\u043e\u0435 \u0443\u043c\u0435\u043d\u0438\u0435":227,[u.DX]:228,"\u041e\u0448\u0438\u0431\u0430\u0442\u044c\u0441\u044f \u2014 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e, \u044f \u0443\u0447\u0443\u0441\u044c.":229,"\u041d\u0435 \u043c\u043e\u0451. \u042f \u043d\u0435 \u0441\u043f\u0440\u0430\u0432\u043b\u044e\u0441\u044c.":230,"\u0412\u0441\u0435 \u0431\u044b\u0441\u0442\u0440\u0435\u0435 \u043c\u0435\u043d\u044f. \u042f \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0445\u043e\u0440\u043e\u0448.":231,[u.d]:232,[u.x]:233,"\u041d\u0435\u0434\u0435\u043b\u044f \u0434\u043e \u0441\u0440\u043e\u043a\u0430":234,[u.t5]:235,[u.Bh]:236,"\u0412\u0441\u0451, \u043d\u0435 \u0443\u0441\u043f\u0435\u0442\u044c. \u042f \u043d\u0435 \u0441\u043f\u0440\u0430\u0432\u043b\u044e\u0441\u044c.":237,"\u041e\u0442\u043b\u043e\u0436\u0443 \u0435\u0449\u0451 \u043d\u0430 \u0434\u0435\u043d\u0451\u043a: \u0441\u0438\u043b \u0432\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043d\u0435\u0442.":238,[u.ro]:239,[u.ux]:240,"\u0427\u0442\u043e-\u0442\u043e \u0441\u043b\u043e\u043c\u0430\u043b\u043e\u0441\u044c":241,[u.fj]:242,[u.Ef]:243,[u.eQ]:244,"\u041f\u043e\u0447\u0435\u043c\u0443 \u0432\u0441\u0451 \u043b\u043e\u043c\u0430\u0435\u0442\u0441\u044f \u0438\u043c\u0435\u043d\u043d\u043e \u0443 \u043c\u0435\u043d\u044f?":245,[u.iQ]:246,"\u041d\u0443 \u0438 \u043f\u0443\u0441\u0442\u044c \u0441\u043b\u043e\u043c\u0430\u043d\u043e. \u041a\u0430\u043a\u0430\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u0430.":247,"\u041a\u0440\u0438\u0442\u0438\u043a\u0430 \u043f\u0440\u0438 \u0432\u0441\u0435\u0445":248,[u.sy]:249,[u.Fc]:250,"\u0412\u0441\u0451 \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e: \u044f \u043d\u0438 \u043d\u0430 \u0447\u0442\u043e \u043d\u0435 \u0433\u043e\u0436\u0443\u0441\u044c.":251,"\u041f\u0440\u043e\u0441\u0442\u043e \u0438\u0449\u0435\u0442 \u043f\u043e\u0432\u043e\u0434. \u0416\u0434\u0438 \u0443\u0434\u0430\u0440\u0430 \u0432 \u0441\u043f\u0438\u043d\u0443.":252,[u.c7]:253,[u.l]:254,"\u041a\u043e\u043c\u0430\u043d\u0434\u0430 \u043f\u0440\u043e\u0438\u0433\u0440\u0430\u043b\u0430":255,[u.dy]:256,[u.oi]:257,"\u041e\u043f\u044f\u0442\u044c \u0438\u0437-\u0437\u0430 \u043c\u0435\u043d\u044f. \u0412\u0435\u0447\u043d\u043e \u044f \u0432\u0441\u0451 \u043f\u043e\u0440\u0447\u0443.":258,[u.jh]:259,[u.aC]:260,[u.CS]:261,"\u0421\u0442\u0430\u0440\u0430\u044f \u043e\u0431\u0438\u0434\u0430":262,[u.yJ]:263,[u.F5]:264,[u.up]:265,"\u042f \u044d\u0442\u043e\u0433\u043e \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u0440\u043e\u0449\u0443.":266,"\u041f\u043e\u0437\u0432\u043e\u043b\u044e \u0441\u0435\u0431\u0435 \u043f\u043e\u0433\u0440\u0443\u0441\u0442\u0438\u0442\u044c \u043e\u0431 \u044d\u0442\u043e\u043c.":267,"\u0412\u043e\u0442 \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043b\u044e\u0434\u044f\u043c \u0432\u0435\u0440\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f.":268,"\u041b\u0438\u0432\u0435\u043d\u044c":269,[u.vX]:270,[u.ya]:271,"\u0412\u0441\u0451 \u0432\u0441\u0435\u0433\u0434\u0430 \u043f\u0440\u043e\u0442\u0438\u0432 \u043c\u0435\u043d\u044f.":272,[u.nf]:273,[u.Bo]:274,"\u042d\u0442\u043e \u043f\u0440\u043e\u0439\u0434\u0451\u0442. \u0417\u0430\u0432\u0442\u0440\u0430 \u0431\u0443\u0434\u0435\u0442 \u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u0435\u043d\u044c.":275,"\u0417\u0430\u0431\u043e\u043b\u0435\u0442\u044c \u043d\u0435 \u0432\u043e\u0432\u0440\u0435\u043c\u044f":276,[u.DA]:277,[u.bY]:278,"\u041f\u043e\u0447\u0435\u043c\u0443 \u044d\u0442\u043e \u0441\u043b\u0443\u0447\u0438\u043b\u043e\u0441\u044c \u0438\u043c\u0435\u043d\u043d\u043e \u0441\u043e \u043c\u043d\u043e\u0439?!":279,[u.ph]:280,[u.uT]:281,"\u0412\u0441\u0435\u0433\u0434\u0430 \u0442\u0430\u043a. \u0412\u043f\u0435\u0440\u0435\u0434\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u0445\u043e\u0440\u043e\u0448\u0435\u0433\u043e.":282,"\u0414\u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0434\u0440\u0443\u0433\u043e\u043c\u0443":283,[u.ef]:284,[u.M]:285,"\u041f\u043e\u0447\u0435\u043c\u0443 \u0435\u043c\u0443, \u0430 \u043d\u0435 \u043c\u043d\u0435? \u041d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e!":286,"\u041d\u0435 \u0437\u0430\u0441\u043b\u0443\u0436\u0438\u043b. \u041d\u0435 \u0431\u0443\u0434\u0443 \u043f\u043e\u0437\u0434\u0440\u0430\u0432\u043b\u044f\u0442\u044c.":287,[u.EB]:288,"\u041c\u043d\u0435 \u0442\u0430\u043a\u043e\u0433\u043e \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u0432\u0438\u0434\u0430\u0442\u044c.":289,"\u0421\u0432\u043e\u044f \u0447\u0435\u0440\u0442\u0430":290,[u.aF]:291,[u.jf]:292,"\u0421\u043e \u043c\u043d\u043e\u0439 \u0447\u0442\u043e-\u0442\u043e \u0433\u043b\u0443\u0431\u043e\u043a\u043e \u043d\u0435 \u0442\u0430\u043a.":293,[u.qP]:294,"\u0418\u0434\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u043b\u044e\u0434\u0435\u0439 \u043d\u0435 \u0431\u044b\u0432\u0430\u0435\u0442.":295,[u.m8]:296,"\u041c\u043e\u043b\u0447\u0430\u043b\u0438\u0432\u0430\u044f \u0437\u0430\u0431\u043e\u0442\u0430":297,[u.Cd]:298,[u.q9]:299,"\u0422\u0430\u043a \u0438 \u0434\u043e\u043b\u0436\u043d\u043e \u0431\u044b\u0442\u044c. \u041c\u043d\u0435 \u0432\u0441\u0435 \u0434\u043e\u043b\u0436\u043d\u044b.":300,[u.Bw]:301,"\u041d\u0435\u043b\u043e\u0432\u043a\u043e. \u042f \u044d\u0442\u043e\u0433\u043e \u043d\u0435 \u0437\u0430\u0441\u043b\u0443\u0436\u0438\u043b.":302,"\u041f\u0440\u0438\u043c\u0443 \u0438 \u0442\u043e\u0436\u0435 \u0447\u0435\u043c-\u043d\u0438\u0431\u0443\u0434\u044c \u043f\u043e\u0440\u0430\u0434\u0443\u044e.":303,"\u0420\u0435\u0437\u043a\u0438\u0439 \u043e\u0442\u0432\u0435\u0442":304,[u.Q]:305,[u.u1]:306,"\u041e\u0442\u0432\u0435\u0447\u0443 \u0442\u0430\u043a \u0436\u0435. \u0420\u0430\u0441\u0441\u043b\u0430\u0431\u043b\u044e\u0441\u044c \u2014 \u0443\u043d\u0438\u0447\u0442\u043e\u0436\u0430\u0442.":307,"\u041e\u043f\u044f\u0442\u044c \u044f \u043c\u0435\u0448\u0430\u044e. \u042f \u043e\u0431\u0443\u0437\u0430.":308,[u.cc]:309,"\u041e\u0442\u0433\u043e\u0440\u043e\u0436\u0443\u0441\u044c. \u041c\u043d\u0435 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043d\u0443\u0436\u0435\u043d.":310,"\u041e\u0434\u0438\u043d\u043e\u043a\u0438\u0439 \u0432\u0435\u0447\u0435\u0440":311,"\u0412\u0435\u0447\u0435\u0440, \u0432\u0441\u0435 \u0437\u0430\u043d\u044f\u0442\u044b, \u0438 \u0442\u0435\u0431\u0435 \u043e\u0434\u0438\u043d\u043e\u043a\u043e.":312,[u.dP]:313,"\u041d\u0438\u043a\u043e\u043c\u0443 \u044f \u043f\u043e-\u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u043c\u0443 \u043d\u0435 \u043d\u0443\u0436\u0435\u043d.":314,"\u0412\u0441\u0435 \u0440\u0430\u043d\u043e \u0438\u043b\u0438 \u043f\u043e\u0437\u0434\u043d\u043e \u0443\u0445\u043e\u0434\u044f\u0442.":315,[u.oe]:316,[u.i]:317,"\u0422\u044f\u0436\u0451\u043b\u044b\u0435 \u0441\u0443\u043c\u043a\u0438":318,[u.ir]:319,"\u041f\u043e\u043c\u043e\u0433\u0443: \u0434\u0432\u0435 \u043c\u0438\u043d\u0443\u0442\u044b \u2014 \u0438 \u043a\u043e\u043c\u0443-\u0442\u043e \u043b\u0435\u0433\u0447\u0435.":320,"\u041d\u0435 \u043c\u043e\u044f \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0430.":321,[u.ko]:322,[u.nb]:323,"\u0412\u0434\u0440\u0443\u0433 \u044d\u0442\u043e \u0443\u043b\u043e\u0432\u043a\u0430?":324,"\u0427\u0443\u0436\u043e\u0439 \u0443\u0441\u043f\u0435\u0445 \u0432 \u043b\u0435\u043d\u0442\u0435":325,[u.EE]:326,[u.yZ]:327,[u.ta]:328,"\u041d\u0430\u0432\u0435\u0440\u043d\u044f\u043a\u0430 \u0432\u0440\u0451\u0442. \u0412\u0435\u0440\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f \u043d\u0438\u043a\u043e\u043c\u0443.":329,[u.oT]:330,"\u042f \u0445\u0443\u0436\u0435 \u0432\u0441\u0435\u0445.":331,"\u041f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0441\u0432\u043e\u0451":332,[u.z8]:333,"\u041f\u043e\u043a\u0430\u0436\u0443: \u043c\u043e\u0451 \u0442\u0432\u043e\u0440\u0447\u0435\u0441\u0442\u0432\u043e \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u043e.":334,"\u042d\u0442\u043e \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0433\u043b\u0443\u043f\u043e, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c.":335,"\u0417\u0430\u0441\u043c\u0435\u044e\u0442. \u0421\u043f\u0440\u044f\u0447\u0443.":336,[u.lN]:337,"\u0414\u0430 \u043a\u043e\u043c\u0443 \u044d\u0442\u043e \u043d\u0430\u0434\u043e. \u0412\u0441\u0451 \u0431\u0435\u0441\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u043e.":338,"\u0414\u0440\u0443\u0437\u044c\u044f \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442":339,[u._]:340,[u.eG]:341,"\u041f\u0440\u043e\u0449\u0435 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0442\u044c\u0441\u044f.":342,"\u041d\u0443 \u0438 \u0438\u0434\u0438\u0442\u0435 \u0431\u0435\u0437 \u043c\u0435\u043d\u044f. \u041c\u043d\u0435 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043d\u0443\u0436\u0435\u043d.":343,[u.df]:344,"\u0412\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043c\u0435\u043d\u044f \u043d\u0435 \u043f\u043e\u0441\u043b\u0443\u0448\u0430\u044e\u0442.":345,"\xab\u0427\u0442\u043e \u0441 \u0442\u043e\u0431\u043e\u0439?\xbb":346,[u.xN]:347,"\u0421\u043a\u0430\u0436\u0443 \u0447\u0435\u0441\u0442\u043d\u043e, \u0447\u0442\u043e \u043c\u043d\u0435 \u0433\u0440\u0443\u0441\u0442\u043d\u043e.":348,[u.a9]:349,"\u041d\u0435 \u0445\u043e\u0447\u0443 \u0433\u0440\u0443\u0437\u0438\u0442\u044c. \u042f \u0438 \u0442\u0430\u043a \u043e\u0431\u0443\u0437\u0430.":350,[u.gS]:351,"\u041f\u043e\u0434\u0435\u043b\u044e\u0441\u044c: \u0431\u043b\u0438\u0437\u043a\u0438\u0435 \u043c\u043e\u0433\u0443\u0442 \u043f\u043e\u043c\u043e\u0447\u044c.":352,"\u0412\u043b\u0435\u0437\u043b\u0438 \u0431\u0435\u0437 \u043e\u0447\u0435\u0440\u0435\u0434\u0438":353,[u.B0]:354,[u.iq]:355,"\u041f\u0440\u043e\u043c\u043e\u043b\u0447\u0443. \u041d\u0435 \u0432\u044b\u0441\u043e\u0432\u044b\u0432\u0430\u0439\u0441\u044f.":356,[u.lW]:357,[u.A2]:358,[u.pX]:359,"\u0417\u043e\u0432\u0443\u0442 \u0442\u0430\u043d\u0446\u0435\u0432\u0430\u0442\u044c":360,[u.hj]:361,"\u041f\u043e\u0439\u0434\u0443: \u043c\u043d\u0435 \u043c\u043e\u0436\u043d\u043e \u0438\u0433\u0440\u0430\u0442\u044c \u043f\u0440\u043e\u0441\u0442\u043e \u0442\u0430\u043a.":362,"\u0411\u0443\u0434\u0443 \u0432\u044b\u0433\u043b\u044f\u0434\u0435\u0442\u044c \u0433\u043b\u0443\u043f\u043e. \u041f\u043e\u0441\u0438\u0436\u0443.":363,"\u0413\u043b\u0443\u043f\u043e\u0435 \u0432\u0435\u0441\u0435\u043b\u044c\u0435. \u0412\u0441\u0451 \u044d\u0442\u043e \u0431\u0435\u0441\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u043e.":364,[u.ud]:365,"\u0418\u0434\u0443! \u0421\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u043d\u0430 \u043c\u0435\u043d\u044f \u2014 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e.":366,"\u0412\u0435\u0447\u0435\u0440 \u0442\u044f\u0436\u0451\u043b\u043e\u0433\u043e \u0434\u043d\u044f":367,"\u041d\u0430\u0441\u0442\u0443\u043f\u0430\u0435\u0442 \u0432\u0435\u0447\u0435\u0440 \u043e\u0447\u0435\u043d\u044c \u0442\u044f\u0436\u0451\u043b\u043e\u0433\u043e \u0434\u043d\u044f.":368,"\u0427\u0435\u043c\u0443 \u043c\u0435\u043d\u044f \u043d\u0430\u0443\u0447\u0438\u043b \u044d\u0442\u043e\u0442 \u0434\u0435\u043d\u044c?":369,"\u0417\u0430\u0447\u0435\u043c \u0432\u043e\u043e\u0431\u0449\u0435 \u0432\u0441\u0451 \u044d\u0442\u043e?":370,"\u0417\u0430\u0432\u0442\u0440\u0430 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0441\u0432\u0435\u0442\u043b\u0435\u0435.":371,"\u042d\u0442\u043e \u0432\u0441\u0451 \u0438\u0437-\u0437\u0430 \u0434\u0440\u0443\u0433\u0438\u0445. \u041d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e!":372,[u.zk]:373,"\u0427\u0435\u0440\u0435\u0437 \u043f\u044f\u0442\u044c \u043b\u0435\u0442":374,[u.tV]:375,"\u042f \u0441\u043e\u0437\u0434\u0430\u044e \u0441\u0432\u043e\u044e \u0438\u0441\u0442\u043e\u0440\u0438\u044e \u2014 \u0435\u0441\u0442\u044c \u043f\u0430\u0440\u0430 \u0438\u0434\u0435\u0439.":376,"\u0412\u043f\u0435\u0440\u0435\u0434\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u0445\u043e\u0440\u043e\u0448\u0435\u0433\u043e.":377,[u.CE]:378,[u.ai]:379,[u.l0]:380,"\u0417\u043d\u0430\u043a\u043e\u043c\u0430\u044f \u0442\u0440\u0443\u0434\u043d\u043e\u0441\u0442\u044c":381,[u.sh]:382,[u.jO]:383,[u.qO]:384,"\u041c\u043e\u0439 \u043e\u043f\u044b\u0442 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0441\u0442\u043e\u0438\u0442.":385,[u.fF]:386,"\u041d\u0435 \u043f\u043e\u043b\u0435\u0437\u0443 \u2014 \u0432\u0434\u0440\u0443\u0433 \u0441\u043a\u0430\u0436\u0443 \u0433\u043b\u0443\u043f\u043e\u0441\u0442\u044c.":387,"\u0417\u0430\u043a\u0430\u0442":388,[u.o4]:389,[u.eT]:390,"\u041a\u0440\u0430\u0441\u0438\u0432\u043e, \u043d\u043e \u043a\u0430\u043a\u043e\u0439 \u0432 \u044d\u0442\u043e\u043c \u0441\u043c\u044b\u0441\u043b.":391,[u.vR]:392,"\u0412 \u043a\u0430\u0436\u0434\u043e\u043c \u0434\u043d\u0435 \u0435\u0441\u0442\u044c \u0438\u0441\u043a\u0440\u0430.":393,[u.iL]:394,"\u041f\u0440\u043e\u0442\u0438\u0432 \u0441\u0432\u043e\u0438\u0445 \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u0435\u0439":395,[u.s]:396,"\u041e\u0442\u043a\u0430\u0436\u0443\u0441\u044c: \u044f \u0437\u043d\u0430\u044e, \u0447\u0442\u043e \u0434\u043b\u044f \u043c\u0435\u043d\u044f \u0432\u0430\u0436\u043d\u043e.":397,"\u0421\u043e\u0433\u043b\u0430\u0448\u0443\u0441\u044c, \u043b\u0438\u0448\u044c \u0431\u044b \u043d\u0435 \u0432\u044b\u0434\u0435\u043b\u044f\u0442\u044c\u0441\u044f.":398,[u.j2]:399,[u.AM]:400,[u.xa]:401,"\u041d\u0435 \u0443\u0441\u043d\u0443\u0442\u044c":402,[u.zW]:403,[u.uu]:404,[u.Dc]:405,"\u0412\u0434\u0440\u0443\u0433 \u0441\u043b\u0443\u0447\u0438\u0442\u0441\u044f \u0447\u0442\u043e-\u0442\u043e \u0441\u0442\u0440\u0430\u0448\u043d\u043e\u0435?":406,[u.dm]:407,"\u0420\u0430\u0437 \u043d\u0435 \u0441\u043f\u043b\u044e \u2014 \u0431\u0443\u0434\u0443 \u043b\u0438\u0441\u0442\u0430\u0442\u044c \u0434\u043e \u0443\u0442\u0440\u0430.":408}
B.bHe=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u0426\u0435\u043d\u043d\u043e\u0441\u0442\u0438","The Tree of Worth")
B.bG3=new A.e("\u0426\u0435\u043d\u043d\u043e\u0441\u0442\u044c","Worth")
B.bDJ=new A.e("\u042f {\u0434\u043e\u0441\u0442\u043e\u0438\u043d|\u0434\u043e\u0441\u0442\u043e\u0439\u043d\u0430} \u043b\u044e\u0431\u0432\u0438","I am worthy of love")
B.bBg=new A.e("\u042f {\u0446\u0435\u043d\u0435\u043d|\u0446\u0435\u043d\u043d\u0430} {\u0441\u0430\u043c|\u0441\u0430\u043c\u0430} \u043f\u043e \u0441\u0435\u0431\u0435, \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e \u043e\u0442 \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u0439.","I am valuable just as I am, regardless of my achievements.")
B.bAP=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u041d\u0438\u0447\u0442\u043e\u0436\u043d\u043e\u0441\u0442\u0438","The Tree of Worthlessness")
B.bwh=new A.e("\u041d\u0438\u0447\u0442\u043e\u0436\u043d\u043e\u0441\u0442\u044c","Worthlessness")
B.bxK=new A.e("\u041c\u0435\u043d\u044f \u0442\u0435\u0440\u043f\u044f\u0442, \u043f\u043e\u043a\u0430 \u044f {\u043f\u043e\u043b\u0435\u0437\u0435\u043d|\u043f\u043e\u043b\u0435\u0437\u043d\u0430}","I am tolerated only as long as I am useful")
B.bCB=new A.e("\u042f {\u0434\u0435\u0444\u0435\u043a\u0442\u0435\u043d|\u0434\u0435\u0444\u0435\u043a\u0442\u043d\u0430} \u0438 {\u0446\u0435\u043d\u0435\u043d|\u0446\u0435\u043d\u043d\u0430} \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u043e\u0433\u0434\u0430, \u043a\u043e\u0433\u0434\u0430 {\u043f\u043e\u043b\u0435\u0437\u0435\u043d|\u043f\u043e\u043b\u0435\u0437\u043d\u0430} \u0434\u0440\u0443\u0433\u0438\u043c.","I am flawed and only matter when I am of use to others.")
B.bOt=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u0414\u043e\u0432\u0435\u0440\u0438\u044f","The Tree of Trust")
B.bAI=new A.e("\u0414\u043e\u0432\u0435\u0440\u0438\u0435","Trust")
B.bRZ=new A.e("\u041c\u0438\u0440 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u0435\u043d","The world is safe enough")
B.bwK=new A.e(u.jx,"The world is fundamentally friendly and full of possibilities, and I know how to handle real danger.")
B.bHX=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u0412\u0440\u0430\u0436\u0434\u0435\u0431\u043d\u043e\u0441\u0442\u0438","The Tree of Hostility")
B.bOs=new A.e("\u0412\u0440\u0430\u0436\u0434\u0435\u0431\u043d\u043e\u0441\u0442\u044c","Hostility")
B.bOl=new A.e("\u041d\u0435 \u0440\u0430\u0441\u0441\u043b\u0430\u0431\u043b\u044f\u0439\u0441\u044f","Never let your guard down")
B.bME=new A.e(u.p7,"The world is a dangerous place, and people only look out for themselves and will cause pain.")
B.bQw=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u0421\u0438\u043b\u044b","The Tree of Power")
B.bLJ=new A.e("\u0421\u0438\u043b\u0430","Power")
B.bvH=new A.e("\u042f \u0441\u043f\u0440\u0430\u0432\u043b\u044e\u0441\u044c","I can handle this")
B.bB6=new A.e(u.l5,"I have enough inner resources to get through any crisis.")
B.bIt=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u0411\u0435\u0441\u0441\u0438\u043b\u0438\u044f","The Tree of Helplessness")
