B.bzW=new A.e("\u0411\u0443\u0434\u0443\u0449\u0435\u0435 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u0431\u0440\u044b\u043c","The future can be kind")
B.byu=new A.e("\u041c\u0435\u043d\u044f \u0438\u0433\u043d\u043e\u0440\u0438\u0440\u0443\u044e\u0442 \u043d\u0430\u0440\u043e\u0447\u043d\u043e","I am being ignored on purpose")
B.bQq=new A.e("\u0412\u0441\u0435\u043c \u043e\u0442 \u043c\u0435\u043d\u044f \u0447\u0442\u043e-\u0442\u043e \u043d\u0443\u0436\u043d\u043e","Everyone wants something from me")
B.bKU=new A.e("\u041d\u0435 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0439, \u0447\u0442\u043e \u0442\u0435\u0431\u0435 \u0432\u0430\u0436\u043d\u043e","Don't show what matters to you")
B.bN8=new A.e("\u0412\u043e\u0442-\u0432\u043e\u0442 \u0441\u043b\u0443\u0447\u0438\u0442\u0441\u044f \u0447\u0442\u043e-\u0442\u043e \u0441\u0442\u0440\u0430\u0448\u043d\u043e\u0435","Something terrible is about to happen")
